// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 275;
draw.viewbox(0, 0, W, H);

var BLUE = '#2440d6', GREEN = '#2ee62e', GREEN_D = '#28c828', RED = '#ee2211', GREY = '#9aa0a6';

/* ---------- geometry ---------- */
var BASE = 188, UNIT = 108;
var TMIN = -1.9, TMAX = 5.35;
var AXLEN = 318;
var SCALE = AXLEN / (TMAX - TMIN);
var P1X0 = 30, P2CX = 591, P3X0 = 832;
function px1(t) { return P1X0 + (t - TMIN) * SCALE; }
function px2(t) { return P2CX + t * SCALE; }
function px3(t) { return P3X0 + (t - TMIN) * SCALE; }
function yv(v) { return BASE - UNIT * v; }
function fmt(x) { return (Math.round(x * 100) / 100).toFixed(2); }

/* ---------- the underlying band-limited signal ---------- */
var KT = 0.6; /* Nyquist sampling interval of the true signal */
var KC = [[-4, 0], [-3, 0.06], [-2, 0.12], [-1, 0.42], [0, 0.62], [1, 1.0], [2, 0.85],
[3, 0.45], [4, -0.18], [5, -0.22], [6, 0.10], [7, 0.72], [8, 0.30], [9, 0.04], [10, 0]];
