// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 275;
draw.viewbox(0, 0, W, H);

var BLUE = '#2440d6', GREEN = '#2ee62e', GREEN_D = '#28c828', RED = '#ee2211', GREY = '#9aa0a6';

/* ---------- geometry ---------- */
var BASE = 188, UNIT = 108;
var TMIN = -1.9, TMAX = 5.35;
var AXLEN = 318;
var SCALE = AXLEN / (TMAX - TMIN);
var P1X0 = 30, P2CX = 591, P3X0 = 832;
function px1(t) { return P1X0 + (t - TMIN) * SCALE; }
function px2(t) { return P2CX + t * SCALE; }
function px3(t) { return P3X0 + (t - TMIN) * SCALE; }
function yv(v) { return BASE - UNIT * v; }
function fmt(x) { return (Math.round(x * 100) / 100).toFixed(2); }

/* ---------- the underlying band-limited signal ---------- */
var KT = 0.6; /* Nyquist sampling interval of the true signal */
var KC = [[-4, 0], [-3, 0.06], [-2, 0.12], [-1, 0.42], [0, 0.62], [1, 1.0], [2, 0.85],
[3, 0.45], [4, -0.18], [5, -0.22], [6, 0.10], [7, 0.72], [8, 0.30], [9, 0.04], [10, 0]];
function sinc(x) { if (Math.abs(x) < 1e-7) return 1; var p = Math.PI * x; return Math.sin(p) / p; }
function fTrue(t) {
  var s = 0;
  for (var i = 0; i < KC.length; i++) s += KC[i][1] * sinc((t - KC[i][0] * KT) / KT);
  return s;
}

/* ---------- state ---------- */
var state = { Ts: 0.5, mode: 'Copies + sum', showOrig: false, sweepIdx: null, selected: null };
var sweepTimer = null;

/* ---------- layers ---------- */
var bg = draw.rect(W, H).fill('#ffffff');
var stat = draw.group();
var g1 = draw.group(), g2 = draw.group(), g3 = draw.group();

bg.on('click', function () { if (state.selected !== null) { state.selected = null; render(); hidePopup(); } });

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  return t;
}

/* ---------- static scaffolding ---------- */
function drawAxis(x0, x1, y) {
  stat.line(x0, y, x1, y).stroke({ color: '#000', width: 4.5 });
  stat.polygon([[x1, y - 9.5], [x1 + 20, y], [x1, y + 9.5]]).fill('#000');
  var t = stat.text('t').font({ family: 'Georgia, Times New Roman, serif', size: 19, style: 'italic' }).fill('#000');
  halo(t).center(x1 + 34, y + 10);
}
drawAxis(P1X0, P1X0 + AXLEN, BASE);
drawAxis(432, 750, BASE);
drawAxis(P3X0, P3X0 + AXLEN, BASE);

/* panel-2 vertical axis */
stat.line(P2CX, BASE, P2CX, 52).stroke({ color: '#000', width: 4.5 });
stat.polygon([[P2CX - 9.5, 52], [P2CX, 32], [P2CX + 9.5, 52]]).fill('#000');
halo(stat.text('1').font({ family: 'Georgia, Times New Roman, serif', size: 18, style: 'italic' }).fill('#000'))
  .center(P2CX - 17, yv(1) - 1);

/* convolution symbol */
var convSym = stat.circle(20).center(406, BASE - 2).fill('none').stroke({ color: '#000', width: 4 });
convSym.css('cursor', 'pointer');
convSym.on('mousemove', function (e) { showTooltip('convolution:  x_s(t) ∗ sinc(t/Ts)', e); }).on('mouseleave', hideTooltip);
convSym.on('click', function (e) {
  e.stopPropagation();
  showPopup('Convolution', 'Convolving the impulse train with the kernel means: put a copy of the kernel at every impulse, scale it by that impulse\'s weight, and add everything up. That is exactly what the right-hand panel shows.');
});

/* equals sign */
stat.line(796, BASE - 8, 826, BASE - 8).stroke({ color: '#000', width: 4.5 });
stat.line(796, BASE + 8, 826, BASE + 8).stroke({ color: '#000', width: 4.5 });

/* ---------- samples ---------- */
function buildSamples() {
  var Ts = state.Ts, out = [], ext = 1.8;
  var n0 = Math.ceil((TMIN - ext) / Ts), n1 = Math.floor((TMAX + ext) / Ts);
  for (var n = n0; n <= n1; n++) { var t = n * Ts; out.push({ n: n, t: t, v: fTrue(t) }); }
  return out;
}
function recon(t, S, upto) {
  var s = 0, m = (upto == null ? S.length - 1 : upto), Ts = state.Ts;
  for (var i = 0; i <= m; i++) s += S[i].v * sinc((t - S[i].t) / Ts);
  return s;
}

/* ---------- impulse ---------- */
function impulse(group, xc, s, idx, S) {
  var y1 = yv(s.v), dir = s.v >= 0 ? -1 : 1, len = Math.abs(y1 - BASE);
  if (len < 1.5) return;
  var hl = Math.min(13, Math.max(4, len * 0.75)), hw = 5.2;
  var dim = (state.selected !== null && state.selected !== idx);
  var g = group.group().opacity(dim ? 0.3 : 1);
  g.line(xc, BASE, xc, y1).stroke({ color: BLUE, width: (state.selected === idx ? 5.5 : 4) });
  g.polygon([[xc - hw, y1 - dir * hl], [xc + hw, y1 - dir * hl], [xc, y1]]).fill(BLUE);
  var top = Math.min(BASE, y1) - 8, hgt = Math.max(len, 14) + 16;
  var hit = group.rect(15, hgt).move(xc - 7.5, top).fill('#fff').opacity(0).css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    showTooltip('sample n = ' + s.n + '   t = ' + fmt(s.t) + '   x[n] = ' + fmt(s.v), e);
  }).on('mouseleave', hideTooltip);
  hit.on('click', function (e) { e.stopPropagation(); selectSample(idx, S); });
}

function selectSample(idx, S) {
  if (state.selected === idx) { state.selected = null; render(); hidePopup(); return; }
  state.selected = idx; render();
  var s = S[idx];
  showPopup('Sample n = ' + s.n + '  (t = ' + fmt(s.t) + ')',
    'This one sample contributes a single sinc of amplitude ' + fmt(s.v) + ' centred at t = ' + fmt(s.t) +
    '. The small circles mark where that copy is exactly zero — at every other sample instant. Because every copy vanishes at all foreign samples, the red sum is forced to pass precisely through each blue arrow tip.');
}

/* ---------- panel 1 ---------- */
function drawPanel1(S) {
  for (var i = 0; i < S.length; i++) {
    if (S[i].t < TMIN - 1e-6 || S[i].t > TMAX) continue;
    impulse(g1, px1(S[i].t), S[i], i, S);
  }
  var Ts = state.Ts, spacing = Ts * SCALE;
  var marks = [{ p: '\u2212', s: 1, t: -Ts }, { p: '', s: 0, t: 0 }, { p: '', s: 1, t: Ts }, { p: '2', s: 1, t: 2 * Ts }];
  for (var k = 0; k < marks.length; k++) {
    var m = marks[k];
    if (m.t < TMIN || m.t > TMAX) continue;
    if (m.s === 1 && spacing < 19) continue;
    var v = fTrue(m.t);
    var ly = (v < -0.03) ? yv(v) + 24 : BASE + 24;
    mathLabel(g1, px1(m.t), ly, m.s ? (m.p + 'T') : '0', m.s ? 's' : null, 14);
  }
}
function mathLabel(group, cx, cy, main, sub, size) {
  var t1 = group.text(main).font({ family: 'Georgia, Times New Roman, serif', size: size, style: 'italic' }).fill('#000');
  halo(t1); t1.center(cx, cy);
  if (sub) {
    var b = t1.bbox();
    var t2 = group.text(sub).font({ family: 'Georgia, Times New Roman, serif', size: size * 0.72, style: 'italic' }).fill('#000');
    halo(t2); t2.center(b.x2 + size * 0.2, cy + size * 0.3);
    var sh = size * 0.22;
    t1.dx(-sh); t2.dx(-sh);
  }
}

/* ---------- panel 2 ---------- */
function drawPanel2() {
  var a = -3.62, b = 3.62, n = 720, pts = [];
  for (var i = 0; i < n; i++) {
    var t = a + (b - a) * i / (n - 1);
    pts.push([px2(t), yv(sinc(t / state.Ts))]);
  }
  var c = g2.polyline(pts).fill('none').stroke({ color: GREEN, width: 6, linecap: 'round', linejoin: 'round' });
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) { showTooltip('reconstruction kernel  sinc(t / Ts),  Ts = ' + fmt(state.Ts), e); })
    .on('mouseleave', hideTooltip);
  c.on('click', function (e) {
    e.stopPropagation();
    showPopup('The sinc kernel', 'sinc(t/Ts) equals 1 at t = 0 and exactly 0 at every non-zero multiple of Ts. That interpolating property is what makes the sum of shifted copies agree with the samples. Narrow Ts ⇒ narrow kernel; wide Ts ⇒ wide, slowly decaying kernel.');
  });
}

/* ---------- panel 3 ---------- */
function drawPanel3(S) {
  var Ts = state.Ts;
  var showCopies = state.mode !== 'Sum only';
  var showSum = state.mode !== 'Copies only';
  var sweeping = (state.sweepIdx !== null);

  if (state.showOrig) {
    var n = 600, op = [];
    for (var i = 0; i < n; i++) { var t = TMIN + (TMAX - TMIN) * i / (n - 1); op.push([px3(t), yv(fTrue(t))]); }
    var og = g3.polyline(op).fill('none').stroke({ color: GREY, width: 3, linecap: 'round' }).attr('stroke-dasharray', '9,6');
    og.on('mousemove', function (e) { showTooltip('original band-limited signal (before sampling)', e); }).on('mouseleave', hideTooltip);
  }

  if (showCopies) {
    for (var i = 0; i < S.length; i++) {
      if (sweeping && i > state.sweepIdx) continue;
      if (S[i].t < TMIN - 2.2 || S[i].t > TMAX + 1.2) continue;
      if (Math.abs(S[i].v) < 0.012) continue;
      drawCopy(S, i, sweeping && i === state.sweepIdx);
    }
  }

  if (showSum) {
    var upto = sweeping ? state.sweepIdx : null;
    var tEnd = sweeping ? Math.min(TMAX, S[state.sweepIdx].t) : TMAX;
    if (tEnd > TMIN) {
      var np = Math.min(1100, Math.max(160, Math.round((tEnd - TMIN) / Ts * 20)));
      var rp = [];
      for (var k = 0; k < np; k++) {
        var tt = TMIN + (tEnd - TMIN) * k / (np - 1);
        rp.push([px3(tt), yv(recon(tt, S, upto))]);
      }
      var rc = g3.polyline(rp).fill('none')
        .stroke({ color: RED, width: 4.6, linecap: 'round', linejoin: 'round' })
        .opacity(state.selected !== null ? 0.35 : 1).css('cursor', 'pointer');
      rc.on('mousemove', function (e) { showTooltip('reconstruction  r(t) = Σ x[n]·sinc((t − nTs)/Ts)', e); })
        .on('mouseleave', hideTooltip);
      rc.on('click', function (e) {
        e.stopPropagation();
        showPopup('The reconstructed signal', 'The red curve is the pointwise sum of every dashed green copy. It touches each blue sample tip because all other copies are zero there. If the samples were taken faster than the Nyquist rate this sum is the original signal exactly.');
      });
    }
  }

  for (var j = 0; j < S.length; j++) {
    if (S[j].t < TMIN - 1e-6 || S[j].t > TMAX) continue;
    impulse(g3, px3(S[j].t), S[j], j, S);
  }

  if (state.selected !== null && S[state.selected]) {
    for (var m = 0; m < S.length; m++) {
      if (m === state.selected) continue;
      if (S[m].t < TMIN || S[m].t > TMAX) continue;
      g3.circle(7).center(px3(S[m].t), BASE).fill('#fff').stroke({ color: GREEN_D, width: 1.8 });
    }
  }
}

function drawCopy(S, i, active) {
  var s = S[i], Ts = state.Ts;
  var a = Math.max(TMIN, s.t - 6.5 * Ts), b = Math.min(TMAX, s.t + 6.5 * Ts);
  if (b - a < 0.05) return;
  var n = Math.min(420, Math.max(60, Math.round((b - a) / Ts * 24))), pts = [];
  for (var k = 0; k < n; k++) {
    var t = a + (b - a) * k / (n - 1);
    pts.push([px3(t), yv(s.v * sinc((t - s.t) / Ts))]);
  }
  var sel = (state.selected === i);
  var dim = (state.selected !== null && !sel);
  var pl = g3.polyline(pts).fill('none')
    .stroke({ color: (sel || active) ? GREEN_D : GREEN, width: (sel || active) ? 3.4 : 1.9, linecap: 'round', linejoin: 'round' })
    .opacity(dim ? 0.13 : (sel || active ? 1 : 0.95));
  if (!sel && !active) pl.attr('stroke-dasharray', '7,5');
  pl.css('cursor', 'pointer');
  pl.on('mousemove', function (e) {
    showTooltip('sinc copy of sample n = ' + s.n + ' :  ' + fmt(s.v) + ' · sinc((t − ' + fmt(s.t) + ')/Ts)', e);
  }).on('mouseleave', hideTooltip);
  pl.on('click', function (e) { e.stopPropagation(); selectSample(i, S); });
}

/* ---------- master render ---------- */
function render() {
  g1.clear(); g2.clear(); g3.clear();
  var S = buildSamples();
  drawPanel1(S);
  drawPanel2();
  drawPanel3(S);
}

/* ---------- interactions ---------- */
function stopSweep() { if (sweepTimer) { clearInterval(sweepTimer); sweepTimer = null; } state.sweepIdx = null; }

function update_samplingInterval(v) {
  stopSweep();
  state.Ts = v; state.selected = null;
  updateNyq(); render();
}
function toggle_copyVisibility(val) { state.mode = val; render(); }
function toggle_showOriginal(on) { state.showOrig = !!on; render(); }

function trigger_convolutionSweep() {
  stopSweep();
  state.selected = null;
  var S = buildSamples();
  var start = 0; while (start < S.length - 1 && S[start].t < TMIN - state.Ts * 0.5) start++;
  var last = S.length - 1; while (last > 0 && S[last].t > TMAX) last--;
  if (last <= start) { render(); return; }
  state.sweepIdx = start; render();
  var dt = Math.max(110, Math.round(2800 / (last - start + 1)));
  sweepTimer = setInterval(function () {
    if (state.sweepIdx === null || state.sweepIdx >= last) { stopSweep(); render(); return; }
    state.sweepIdx++; render();
  }, dt);
}

function updateNyq() {
  var el = document.getElementById('nyqNote');
  if (!el) return;
  if (state.Ts <= KT + 1e-9) {
    el.innerHTML = 'Nyquist interval = 0.60 &nbsp;→&nbsp; <b style="color:#178017">sampling fine: exact</b>';
  } else {
    el.innerHTML = 'Nyquist interval = 0.60 &nbsp;→&nbsp; <b style="color:#c00000">under-sampled: aliasing</b>';
  }
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The three ingredients', st: { Ts: 0.5, mode: 'Copies + sum', orig: false },
    text: 'On the left the signal exists only as blue sample impulses; in the middle sits the sinc reconstruction kernel with peak 1. The right panel is their convolution — the continuous signal recovered from discrete data.'
  },
  {
    title: 'One sample, one sinc', st: { Ts: 0.5, mode: 'Copies only', orig: false },
    text: 'Hide the sum: each blue sample plants a sinc scaled to its own height and centred at its own time. Every copy crosses zero at all the other sample instants. Click a blue sample to isolate its copy.'
  },
  {
    title: 'Sweeping the convolution', st: { Ts: 0.5, mode: 'Copies + sum', orig: false, sweep: true },
    text: 'The kernel steps across the samples one at a time and the running red total accumulates from left to right — convolution is literally this shift, scale and add process.'
  },
  {
    title: 'The sum is the signal', st: { Ts: 0.5, mode: 'Sum only', orig: false },
    text: 'Hide the copies and only the red curve remains: a smooth waveform passing exactly through every blue tip. Nothing was invented — the samples fully determined it.'
  },
  {
    title: 'Sampling too slowly', st: { Ts: 1.4, mode: 'Copies + sum', orig: true },
    text: 'Widen T_s past the Nyquist interval 0.60: the sincs become broad and overlap heavily, and the red reconstruction drifts away from the grey original between samples — this is aliasing.'
  },
  {
    title: 'Sampling densely', st: { Ts: 0.25, mode: 'Sum only', orig: true },
    text: 'Shrink T_s: narrow, tightly packed sincs rebuild the signal almost perfectly — red lies on top of the grey original. Quality is set by sample spacing, not by the kernel\'s shape.'
  }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.st;
  stopSweep();
  state.selected = null;
  state.Ts = st.Ts; state.mode = st.mode; state.showOrig = !!st.orig;
  var sl = document.getElementById('samplingIntervalInput');
  if (sl) sl.value = st.Ts;
  var ov = document.getElementById('samplingIntervalVal');
  if (ov) ov.value = st.Ts.toFixed(2);
  var sel = document.getElementById('copyVisibilityInput');
  if (sel) sel.value = st.mode;
  var cb = document.getElementById('showOriginalInput');
  if (cb) cb.checked = !!st.orig;
  document.getElementById('demoNarration').innerHTML = '<b>' + (curStep + 1) + '. ' + s.title + '</b><br>' + s.text;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  updateNyq();
  render();
  if (st.sweep) trigger_convolutionSweep();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot ---------- */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

