  for (var j = 0; j < items.length; j++) {
    var it = items[j], x0 = it.x - it.w / 2;
    it.t1.center(x0 + it.w1 / 2, it.y);
    if (it.t2) it.t2.center(x0 + it.w1 + it.w2 / 2, it.y + size * 0.27);
    /* axis tick */
    g1.line(px1(it.t), BASE - 5, px1(it.t), BASE + 6).stroke({ color: '#000', width: 2 });
    /* leader when the label had to move */
    if (Math.abs(it.x - px1(it.t)) > 2.5) {
      g1.line(px1(it.t), BASE + 7, it.x, it.y - size * 0.58)
        .stroke({ color: '#555', width: 1.1 }).back();
    }
    it.g.front();
  }
}

/* ---------- panel 2 ---------- */
function drawPanel2() {
  var lim = Math.min(3.5 * state.Ts, HALF2 / SCALE2);
  var n = 620, pts = [];
  for (var i = 0; i < n; i++) {
    var t = -lim + 2 * lim * i / (n - 1);
    pts.push([px2(t), yv(sinc(t / state.Ts))]);
  }
  var c = g2.polyline(pts).fill('none').stroke({ color: GREEN, width: 5.6, linecap: 'round', linejoin: 'round' });
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) { showTooltip('reconstruction kernel  sinc(t / Ts),  Ts = ' + fmt(state.Ts), e); })
    .on('mouseleave', hideTooltip);
  c.on('click', function (e) {
    e.stopPropagation();
    showPopup('The sinc kernel', 'sinc(t/Ts) equals 1 at t = 0 and exactly 0 at every non-zero multiple of Ts. That interpolating property is what makes the sum of shifted copies agree with the samples. Narrow Ts ⇒ narrow kernel; wide Ts ⇒ wide, slowly decaying kernel.');
  });
}

/* ---------- panel 3 ---------- */
function drawPanel3(S) {
  var Ts = state.Ts;
  var showCopies = state.mode !== 'Sum only';
  var showSum = state.mode !== 'Copies only';
  var sweeping = (state.sweepIdx !== null);

  if (state.showOrig) {
    var n = 560, op = [];
    for (var i = 0; i < n; i++) { var t = TMIN + (TMAX - TMIN) * i / (n - 1); op.push([px3(t), yv(fTrue(t))]); }
    var og = g3.polyline(op).fill('none').stroke({ color: GREY, width: 2.8, linecap: 'round' }).attr('stroke-dasharray', '8,5');
    og.on('mousemove', function (e) { showTooltip('original band-limited signal (before sampling)', e); }).on('mouseleave', hideTooltip);
  }

  if (showCopies) {
    for (var i2 = 0; i2 < S.length; i2++) {
      if (sweeping && i2 > state.sweepIdx) continue;
      if (S[i2].t < TMIN - 2.4 || S[i2].t > TMAX + 1.4) continue;
      if (Math.abs(S[i2].v) < 0.012) continue;
      drawCopy(S, i2, sweeping && i2 === state.sweepIdx);
    }
  }

  if (showSum) {
    var upto = sweeping ? state.sweepIdx : null;
    var tEnd = sweeping ? Math.min(TMAX, S[state.sweepIdx].t) : TMAX;
    if (tEnd > TMIN) {
      var np = Math.min(1000, Math.max(160, Math.round((tEnd - TMIN) / Ts * 20)));
      var rp = [];
      for (var k = 0; k < np; k++) {
        var tt = TMIN + (tEnd - TMIN) * k / (np - 1);
        rp.push([px3(tt), yv(recon(tt, S, upto))]);
      }
      var rc = g3.polyline(rp).fill('none')
        .stroke({ color: RED, width: 4.4, linecap: 'round', linejoin: 'round' })
        .opacity(state.selected !== null ? 0.35 : 1).css('cursor', 'pointer');
      rc.on('mousemove', function (e) { showTooltip('reconstruction  r(t) = Σ x[n]·sinc((t − nTs)/Ts)', e); })
        .on('mouseleave', hideTooltip);
      rc.on('click', function (e) {
        e.stopPropagation();
        showPopup('The reconstructed signal', 'The red curve is the pointwise sum of every dashed green copy. It touches each blue sample tip because all other copies are zero there. If the samples were taken faster than the Nyquist rate this sum is the original signal exactly.');
      });
    }
  }

  for (var j = 0; j < S.length; j++) {
    if (S[j].t < TMIN - 1e-6 || S[j].t > TMAX) continue;
    impulse(g3, px3(S[j].t), S[j], j, S);
  }

  if (state.selected !== null && S[state.selected]) {
    for (var m = 0; m < S.length; m++) {
      if (m === state.selected) continue;
      if (S[m].t < TMIN || S[m].t > TMAX) continue;
      g3.circle(7).center(px3(S[m].t), BASE).fill('#fff').stroke({ color: GREEN_D, width: 1.8 });
    }
  }
}

function drawCopy(S, i, active) {
  var s = S[i], Ts = state.Ts;
  var a = Math.max(TMIN, s.t - 6.5 * Ts), b = Math.min(TMAX, s.t + 6.5 * Ts);
  if (b - a < 0.05) return;
  var n = Math.min(400, Math.max(60, Math.round((b - a) / Ts * 24))), pts = [];
  for (var k = 0; k < n; k++) {
    var t = a + (b - a) * k / (n - 1);
    pts.push([px3(t), yv(s.v * sinc((t - s.t) / Ts))]);
  }
  var sel = (state.selected === i);
  var dim = (state.selected !== null && !sel);
  var pl = g3.polyline(pts).fill('none')
    .stroke({ color: (sel || active) ? GREEN_D : GREEN, width: (sel || active) ? 3.4 : 1.9, linecap: 'round', linejoin: 'round' })
    .opacity(dim ? 0.13 : (sel || active ? 1 : 0.95));
  if (!sel && !active) pl.attr('stroke-dasharray', '7,5');
  pl.css('cursor', 'pointer');
  pl.on('mousemove', function (e) {
    showTooltip('sinc copy of sample n = ' + s.n + ' :  ' + fmt(s.v) + ' · sinc((t − ' + fmt(s.t) + ')/Ts)', e);
  }).on('mouseleave', hideTooltip);
  pl.on('click', function (e) { e.stopPropagation(); selectSample(i, S); });
}

/* ---------- master render ---------- */
function render() {
  g1.clear(); g2.clear(); g3.clear();
  var S = buildSamples();
  drawPanel1(S);
  drawPanel2();
  drawPanel3(S);
}

/* ---------- interactions ---------- */
function stopSweep() { if (sweepTimer) { clearInterval(sweepTimer); sweepTimer = null; } state.sweepIdx = null; }

function update_samplingInterval(v) {
  stopSweep();
  state.Ts = v; state.selected = null;
  updateNyq(); render();
}
function toggle_copyVisibility(val) { state.mode = val; render(); }
function toggle_showOriginal(on) { state.showOrig = !!on; render(); }

function trigger_convolutionSweep() {
  stopSweep();
  state.selected = null;
  var S = buildSamples();
  var start = 0; while (start < S.length - 1 && S[start].t < TMIN - state.Ts * 0.5) start++;
  var last = S.length - 1; while (last > 0 && S[last].t > TMAX) last--;
  if (last <= start) { render(); return; }
  state.sweepIdx = start; render();
  var dt = Math.max(110, Math.round(2800 / (last - start + 1)));
  sweepTimer = setInterval(function () {
    if (state.sweepIdx === null || state.sweepIdx >= last) { stopSweep(); render(); return; }
    state.sweepIdx++; render();
  }, dt);
}

function updateNyq() {
  var el = document.getElementById('nyqNote');
  if (!el) return;
  if (state.Ts <= KT + 1e-9) {
    el.innerHTML = 'Nyquist interval = 0.55 &nbsp;→&nbsp; <b style="color:#178017">sampling fine: exact</b>';
  } else {
    el.innerHTML = 'Nyquist interval = 0.55 &nbsp;→&nbsp; <b style="color:#c00000">under-sampled: aliasing</b>';
  }
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The three ingredients', st: { Ts: 0.5, mode: 'Copies + sum', orig: false },
    text: 'On the left the signal exists only as blue sample impulses; in the middle sits the sinc reconstruction kernel with peak 1. The right panel is their convolution — the continuous signal recovered from discrete data.'
  },
  {
    title: 'One sample, one sinc', st: { Ts: 0.5, mode: 'Copies only', orig: false },
    text: 'Hide the sum: each blue sample plants a sinc scaled to its own height and centred at its own time. Every copy crosses zero at all the other sample instants. Click a blue sample to isolate its copy.'
  },
  {
    title: 'Sweeping the convolution', st: { Ts: 0.5, mode: 'Copies + sum', orig: false, sweep: true },
    text: 'The kernel steps across the samples one at a time and the running red total accumulates from left to right — convolution is literally this shift, scale and add process.'
  },
  {
    title: 'The sum is the signal', st: { Ts: 0.5, mode: 'Sum only', orig: false },
    text: 'Hide the copies and only the red curve remains: a smooth waveform passing exactly through every blue tip. Nothing was invented — the samples fully determined it.'
  },
  {
    title: 'Sampling too slowly', st: { Ts: 1.4, mode: 'Copies + sum', orig: true },
    text: 'Widen T_s past the Nyquist interval 0.55: the sincs become broad and overlap heavily, and the red reconstruction drifts away from the grey original between samples — this is aliasing.'
  },
  {
    title: 'Sampling densely', st: { Ts: 0.25, mode: 'Sum only', orig: true },
    text: 'Shrink T_s: narrow, tightly packed sincs rebuild the signal almost perfectly — red lies on top of the grey original. Quality is set by sample spacing, not by the kernel\'s shape.'
  }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.st;
  stopSweep();
  state.selected = null;
  state.Ts = st.Ts; state.mode = st.mode; state.showOrig = !!st.orig;
  var sl = document.getElementById('samplingIntervalInput');
  if (sl) sl.value = st.Ts;
  var ov = document.getElementById('samplingIntervalVal');
  if (ov) ov.value = st.Ts.toFixed(2);
  var sel = document.getElementById('copyVisibilityInput');
  if (sel) sel.value = st.mode;
  var cb = document.getElementById('showOriginalInput');
  if (cb) cb.checked = !!st.orig;
  document.getElementById('demoNarration').innerHTML = '<b>' + (curStep + 1) + '. ' + s.title + '</b><br>' + s.text;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  updateNyq();
  render();
  if (st.sweep) trigger_convolutionSweep();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot ---------- */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A continuous signal is reconstructed from its samples by convolving the impulse train with a sinc kernel: every sample drops a scaled, shifted copy of the sinc, and the superposition of all copies is the reconstructed waveform.
KEY INSIGHT (what students should walk away understanding): Reconstruction is not guessing between samples — each sample simply contributes its own scaled sinc that is zero at every other sample, so the sum automatically threads through all samples and is the unique bandlimited signal behind them.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
