Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span id="demoNarration" style="display:block;font-size:12.5px;line-height:1.5;min-height:82px"></span>
<span style="display:flex;gap:8px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:12px">Step 1 / 6</span>
  <button onclick="nextStep()">▶</button>
</span>
<label><span>Sampling interval <i>T</i><sub>s</sub> = <output id="samplingIntervalVal">0.50</output></span>
  <input id="samplingIntervalInput" type="range" min="0.2" max="1.6" step="0.05" value="0.5"
   oninput="document.getElementById('samplingIntervalVal').value=(+this.value).toFixed(2);update_samplingInterval(+this.value)"></label>
<span id="nyqNote" style="font-size:11.5px"></span>
<label><span>Sinc copies:</span>
  <select id="copyVisibilityInput" onchange="toggle_copyVisibility(this.value)">
    <option>Copies + sum</option>
    <option>Copies only</option>
    <option>Sum only</option>
  </select></label>
<button id="sweepBtn" onclick="trigger_convolutionSweep()">▶ Sweep kernel across samples</button>
<label style="flex-direction:row;align-items:center;gap:6px"><input id="showOriginalInput" type="checkbox" onchange="toggle_showOriginal(this.checked)"> <span>Show original signal (grey)</span></label>
<span style="font-size:11.5px;line-height:1.55;border-top:1px solid #dcdfe3;padding-top:6px">
  <b style="color:#2440d6">▮</b> blue = samples &nbsp;·&nbsp; <b style="color:#1faa1f">– –</b> green = individual sinc copies &nbsp;·&nbsp; <b style="color:#ee2211">▬</b> red = reconstruction<br>
  <i>Click a blue sample (either panel) to isolate its sinc copy; click empty space to clear.</i>
</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 680, H = 218;
draw.viewbox(0, 0, W, H);

var BLUE = '#2440d6', GREEN = '#2ee62e', GREEN_D = '#1faa1f', RED = '#ee2211', GREY = '#9aa0a6';
var SERIF = 'Georgia, "Times New Roman", serif';

/* ---------- geometry ---------- */
var BASE = 110, UNIT = 64;
var TMIN = -1.55, TMAX = 4.70;
var AXLEN = 168;
var SCALE = AXLEN / (TMAX - TMIN);
var P1X0 = 8, CONVX = 220, P2CX = 320, HALF2 = 84, EQX = 452, P3X0 = 474;
var SCALE2 = 45;

function px1(t) { return P1X0 + (t - TMIN) * SCALE; }
function px2(t) { return P2CX + t * SCALE2; }
function px3(t) { return P3X0 + (t - TMIN) * SCALE; }
function yv(v) { return BASE - UNIT * v; }
function fmt(x) { return (Math.round(x * 100) / 100).toFixed(2); }

/* ---------- underlying band-limited signal ---------- */
var KT = 0.55;                              /* Nyquist sampling interval */
var KC = [[-4, 0], [-3, 0.06], [-2, 0.12], [-1, 0.42], [0, 0.62], [1, 1.0], [2, 0.85],
[3, 0.45], [4, -0.18], [5, -0.24], [6, 0.10], [7, 0.74], [8, 0.30], [9, 0.04], [10, 0]];
function sinc(x) { if (Math.abs(x) < 1e-7) return 1; var p = Math.PI * x; return Math.sin(p) / p; }
function fTrue(t) {
  var s = 0;
  for (var i = 0; i < KC.length; i++) s += KC[i][1] * sinc((t - KC[i][0] * KT) / KT);
  return s;
}

/* ---------- state ---------- */
var state = { Ts: 0.5, mode: 'Copies + sum', showOrig: false, sweepIdx: null, selected: null };
var sweepTimer = null;

/* ---------- layers ---------- */
draw.rect(W, H).fill('#ffffff');
var stat = draw.group();
var g1 = draw.group(), g2 = draw.group(), g3 = draw.group();

draw.on('click', function () { if (state.selected !== null) { state.selected = null; render(); hidePopup(); } });

function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

/* ---------- static scaffolding ---------- */
function drawAxis(x0, y) {
  var x1 = x0 + AXLEN;
  stat.line(x0, y, x1, y).stroke({ color: '#000', width: 3.6 });
  stat.polygon([[x1, y - 7.5], [x1 + 13, y], [x1, y + 7.5]]).fill('#000');
  var t = stat.text('t').font({ family: SERIF, size: 24, style: 'italic', weight: 'bold' }).fill('#000');
  halo(t).center(x1 + 24, y + 10);
}
drawAxis(P1X0, BASE);
drawAxis(P2CX - HALF2, BASE);
drawAxis(P3X0, BASE);

/* panel-2 vertical axis */
stat.line(P2CX, BASE, P2CX, 32).stroke({ color: '#000', width: 3.6 });
stat.polygon([[P2CX - 7.5, 32], [P2CX, 18], [P2CX + 7.5, 32]]).fill('#000');
halo(stat.text('1').font({ family: SERIF, size: 21, style: 'italic', weight: 'bold' }).fill('#000'))
  .center(P2CX - 14, yv(1) + 1);

/* convolution symbol */
var convSym = stat.circle(19).center(CONVX, BASE - 2).fill('none').stroke({ color: '#000', width: 4 });
convSym.css('cursor', 'pointer');
convSym.on('mousemove', function (e) { showTooltip('convolution:  x_s(t) ∗ sinc(t / T_s)', e); }).on('mouseleave', hideTooltip);
convSym.on('click', function (e) {
  e.stopPropagation();
  showPopup('Convolution', 'Convolving the impulse train with the kernel means: put a copy of the kernel at every impulse, scale it by that impulse\'s weight, and add everything up. That is exactly what the right-hand panel shows.');
});

/* equals sign */
stat.line(EQX - 12, BASE - 9, EQX + 12, BASE - 9).stroke({ color: '#000', width: 4.4 });
stat.line(EQX - 12, BASE + 7, EQX + 12, BASE + 7).stroke({ color: '#000', width: 4.4 });

/* ---------- samples ---------- */
function buildSamples() {
  var Ts = state.Ts, out = [], ext = 2.2;
  var n0 = Math.ceil((TMIN - ext) / Ts), n1 = Math.floor((TMAX + ext) / Ts);
  for (var n = n0; n <= n1; n++) { var t = n * Ts; out.push({ n: n, t: t, v: fTrue(t) }); }
  return out;
}
function recon(t, S, upto) {
  var s = 0, m = (upto == null ? S.length - 1 : upto), Ts = state.Ts;
  for (var i = 0; i <= m; i++) s += S[i].v * sinc((t - S[i].t) / Ts);
  return s;
}

/* ---------- impulse ---------- */
function impulse(group, xc, s, idx, S) {
  var y1 = yv(s.v), dir = s.v >= 0 ? -1 : 1, len = Math.abs(y1 - BASE);
  if (len < 1.5) return;
  var hl = Math.min(11, Math.max(4, len * 0.75)), hw = 4.2;
  var dim = (state.selected !== null && state.selected !== idx);
  var g = group.group().opacity(dim ? 0.28 : 1);
  g.line(xc, BASE, xc, y1).stroke({ color: BLUE, width: (state.selected === idx ? 4.4 : 3) });
  g.polygon([[xc - hw, y1 - dir * hl], [xc + hw, y1 - dir * hl], [xc, y1]]).fill(BLUE);
  var top = Math.min(BASE, y1) - 7, hgt = Math.max(len, 12) + 14;
  var hit = group.rect(13, hgt).move(xc - 6.5, top).fill('#fff').opacity(0).css('cursor', 'pointer');
  hit.on('mousemove', function (e) {
    showTooltip('sample n = ' + s.n + '   t = ' + fmt(s.t) + '   x[n] = ' + fmt(s.v), e);
  }).on('mouseleave', hideTooltip);
  hit.on('click', function (e) { e.stopPropagation(); selectSample(idx, S); });
}

function selectSample(idx, S) {
  if (state.selected === idx) { state.selected = null; render(); hidePopup(); return; }
  state.selected = idx; render();
  var s = S[idx];
  showPopup('Sample n = ' + s.n + '  (t = ' + fmt(s.t) + ')',
    'This one sample contributes a single sinc of amplitude ' + fmt(s.v) + ' centred at t = ' + fmt(s.t) +
    '. The small circles mark where that copy is exactly zero — at every other sample instant. Because every copy vanishes at all foreign samples, the red sum is forced to pass precisely through each blue arrow tip.');
}

/* ---------- panel 1 ---------- */
function drawPanel1(S) {
  for (var i = 0; i < S.length; i++) {
    if (S[i].t < TMIN - 1e-6 || S[i].t > TMAX) continue;
    impulse(g1, px1(S[i].t), S[i], i, S);
  }
  drawTickLabels();
}

/* ---- staggered tick labels: each label sits exactly under its own tick,
        crowding is solved with extra rows + thin vertical guides ---- */
var LBL = 21, ROWY = [BASE + 32, BASE + 60, BASE + 88];

function mkLabel(group, main, sub) {
  var g = group.group();
  var t1 = g.text(main).font({ family: SERIF, size: LBL, style: 'italic', weight: 'bold' }).fill('#000');
  halo(t1);
  var t2 = null, w2 = 0;
  if (sub) {
    t2 = g.text(sub).font({ family: SERIF, size: LBL * 0.62, style: 'italic', weight: 'bold' }).fill('#000');
    halo(t2); w2 = t2.bbox().width + 1.5;
  }
  var w1 = t1.bbox().width;
  return {
    g: g, t1: t1, t2: t2, w: w1 + w2, w1: w1, w2: w2,
    place: function (cx, cy) {
      var x0 = cx - this.w / 2;
      this.t1.center(x0 + this.w1 / 2, cy);
      if (this.t2) this.t2.center(x0 + this.w1 + this.w2 / 2, cy + LBL * 0.26);
    }
  };
}

function guide(x, cy) {
  g1.line(x, BASE + 7, x, cy - LBL * 0.62).stroke({ color: '#8a8f96', width: 0.9 }).back();
  g1.line(x, BASE - 5, x, BASE + 6).stroke({ color: '#000', width: 2 });
}

function fitsRows(items, rows) {
  for (var r = 0; r < rows; r++) {
    var prev = null;
    for (var i = r; i < items.length; i += rows) {
      if (prev && items[i].x - prev.x < (prev.lab.w + items[i].lab.w) / 2 + 6) return false;
      prev = items[i];
    }
  }
  return true;
}

function drawTickLabels() {
  var Ts = state.Ts, spacing = Ts * SCALE;

  /* extremely dense sampling: show only 0 and a T_s span measure */
  if (spacing < 11) {
    var zero = mkLabel(g1, '0', null);
    zero.place(px1(0), ROWY[1]); guide(px1(0), ROWY[1]);
    var xa = px1(0), xb = px1(Ts), ym = ROWY[0];
    g1.line(xa, BASE + 7, xa, ym - 6).stroke({ color: '#8a8f96', width: 0.9 });
    g1.line(xb, BASE + 7, xb, ym - 6).stroke({ color: '#8a8f96', width: 0.9 });
    g1.line(xa, ym, xb, ym).stroke({ color: '#333', width: 1.4 });
    g1.polygon([[xa, ym], [xa + 5, ym - 3], [xa + 5, ym + 3]]).fill('#333');
    g1.polygon([[xb, ym], [xb - 5, ym - 3], [xb - 5, ym + 3]]).fill('#333');
    var sp = mkLabel(g1, 'T', 's');
    var lx = xb + 10 + sp.w / 2;
    g1.line(xb, ym, lx - sp.w / 2 - 3, ym).stroke({ color: '#8a8f96', width: 0.9 });
    sp.place(lx, ym + 2);
    return;
  }

  var defs = [
    { t: 0, main: '0', sub: null },
    { t: Ts, main: 'T', sub: 's' },
    { t: -Ts, main: '\u2212T', sub: 's' },
    { t: 2 * Ts, main: '2T', sub: 's' }
  ];
  var pool = [];
  for (var i = 0; i < defs.length; i++) {
    var d = defs[i];
    if (d.t < TMIN + 0.04 || d.t > TMAX - 0.12) continue;
    pool.push({ t: d.t, x: px1(d.t), lab: mkLabel(g1, d.main, d.sub), pri: i });
  }
  var chosen = null, rowsUsed = 1;
  for (var n = pool.length; n >= 1 && !chosen; n--) {
    var subset = pool.slice(0, n).slice().sort(function (a, b) { return a.x - b.x; });
    for (var r = 1; r <= 3; r++) {
      if (fitsRows(subset, r)) { chosen = subset; rowsUsed = r; break; }
    }
  }
  if (!chosen) chosen = [pool[0]];
  for (var k = 0; k < pool.length; k++) if (chosen.indexOf(pool[k]) === -1) pool[k].lab.g.remove();
  for (var j = 0; j < chosen.length; j++) {
    var it = chosen[j], cy = ROWY[j % rowsUsed];
    guide(it.x, cy);
    it.lab.place(it.x, cy);
    it.lab.g.front();
  }
}

/* ---------- panel 2 ---------- */
function drawPanel2() {
  var lim = Math.min(3.5 * state.Ts, HALF2 / SCALE2);
  var n = 620, pts = [];
  for (var i = 0; i < n; i++) {
    var t = -lim + 2 * lim * i / (n - 1);
    pts.push([px2(t), yv(sinc(t / state.Ts))]);
  }
  var c = g2.polyline(pts).fill('none').stroke({ color: GREEN, width: 4.8, linecap: 'round', linejoin: 'round' });
  c.css('cursor', 'pointer');
  c.on('mousemove', function (e) { showTooltip('reconstruction kernel  sinc(t / T_s),  T_s = ' + fmt(state.Ts), e); })
    .on('mouseleave', hideTooltip);
  c.on('click', function (e) {
    e.stopPropagation();
    showPopup('The sinc kernel', 'sinc(t/T_s) equals 1 at t = 0 and exactly 0 at every non-zero multiple of T_s. That interpolating property is what makes the sum of shifted copies agree with the samples. Narrow T_s ⇒ narrow kernel; wide T_s ⇒ wide, slowly decaying kernel.');
  });
}

/* ---------- panel 3 ---------- */
function drawPanel3(S) {
  var Ts = state.Ts;
  var showCopies = state.mode !== 'Sum only';
  var showSum = state.mode !== 'Copies only';
  var sweeping = (state.sweepIdx !== null);

  if (state.showOrig) {
    var n = 560, op = [];
    for (var i = 0; i < n; i++) { var t = TMIN + (TMAX - TMIN) * i / (n - 1); op.push([px3(t), yv(fTrue(t))]); }
    var og = g3.polyline(op).fill('none').stroke({ color: GREY, width: 2.4, linecap: 'round' }).attr('stroke-dasharray', '7,4');
    og.on('mousemove', function (e) { showTooltip('original band-limited signal (before sampling)', e); }).on('mouseleave', hideTooltip);
  }

  if (showCopies) {
    for (var i2 = 0; i2 < S.length; i2++) {
      if (sweeping && i2 > state.sweepIdx) continue;
      if (S[i2].t < TMIN - 2.4 || S[i2].t > TMAX + 1.4) continue;
      if (Math.abs(S[i2].v) < 0.012) continue;
      drawCopy(S, i2, sweeping && i2 === state.sweepIdx);
    }
  }

  if (showSum) {
    var upto = sweeping ? state.sweepIdx : null;
    var tEnd = sweeping ? Math.min(TMAX, S[state.sweepIdx].t) : TMAX;
    if (tEnd > TMIN) {
      var np = Math.min(1000, Math.max(160, Math.round((tEnd - TMIN) / Ts * 20)));
      var rp = [];
      for (var k = 0; k < np; k++) {
        var tt = TMIN + (tEnd - TMIN) * k / (np - 1);
        rp.push([px3(tt), yv(recon(tt, S, upto))]);
      }
      var rc = g3.polyline(rp).fill('none')
        .stroke({ color: RED, width: 3.8, linecap: 'round', linejoin: 'round' })
        .opacity(state.selected !== null ? 0.35 : 1).css('cursor', 'pointer');
      rc.on('mousemove', function (e) { showTooltip('reconstruction  r(t) = Σ x[n]·sinc((t − nT_s)/T_s)', e); })
        .on('mouseleave', hideTooltip);
      rc.on('click', function (e) {
        e.stopPropagation();
        showPopup('The reconstructed signal', 'The red curve is the pointwise sum of every dashed green copy. It touches each blue sample tip because all other copies are zero there. If the samples were taken faster than the Nyquist rate this sum is the original signal exactly.');
      });
    }
  }

  for (var j = 0; j < S.length; j++) {
    if (S[j].t < TMIN - 1e-6 || S[j].t > TMAX) continue;
    impulse(g3, px3(S[j].t), S[j], j, S);
  }

  if (state.selected !== null && S[state.selected]) {
    for (var m = 0; m < S.length; m++) {
      if (m === state.selected) continue;
      if (S[m].t < TMIN || S[m].t > TMAX) continue;
      g3.circle(6).center(px3(S[m].t), BASE).fill('#fff').stroke({ color: GREEN_D, width: 1.6 });
    }
  }
}

function drawCopy(S, i, active) {
  var s = S[i], Ts = state.Ts;
  var a = Math.max(TMIN, s.t - 6.5 * Ts), b = Math.min(TMAX, s.t + 6.5 * Ts);
  if (b - a < 0.05) return;
  var n = Math.min(400, Math.max(60, Math.round((b - a) / Ts * 24))), pts = [];
  for (var k = 0; k < n; k++) {
    var t = a + (b - a) * k / (n - 1);
    pts.push([px3(t), yv(s.v * sinc((t - s.t) / Ts))]);
  }
  var sel = (state.selected === i);
  var dim = (state.selected !== null && !sel);
  var pl = g3.polyline(pts).fill('none')
    .stroke({ color: (sel || active) ? GREEN_D : GREEN, width: (sel || active) ? 3.0 : 1.7, linecap: 'round', linejoin: 'round' })
    .opacity(dim ? 0.13 : (sel || active ? 1 : 0.95));
  if (!sel && !active) pl.attr('stroke-dasharray', '6,4');
  pl.css('cursor', 'pointer');
  pl.on('mousemove', function (e) {
    showTooltip('sinc copy of sample n = ' + s.n + ' :  ' + fmt(s.v) + ' · sinc((t − ' + fmt(s.t) + ')/T_s)', e);
  }).on('mouseleave', hideTooltip);
  pl.on('click', function (e) { e.stopPropagation(); selectSample(i, S); });
}

/* ---------- master render ---------- */
function render() {
  g1.clear(); g2.clear(); g3.clear();
  var S = buildSamples();
  drawPanel1(S);
  drawPanel2();
  drawPanel3(S);
}

/* ---------- interactions ---------- */
function stopSweep() { if (sweepTimer) { clearInterval(sweepTimer); sweepTimer = null; } state.sweepIdx = null; }

function update_samplingInterval(v) {
  stopSweep();
  state.Ts = v; state.selected = null;
  updateNyq(); render();
}
function toggle_copyVisibility(val) { state.mode = val; render(); }
function toggle_showOriginal(on) { state.showOrig = !!on; render(); }

function trigger_convolutionSweep() {
  stopSweep();
  state.selected = null;
  var S = buildSamples();
  var start = 0; while (start < S.length - 1 && S[start].t < TMIN - state.Ts * 0.5) start++;
  var last = S.length - 1; while (last > 0 && S[last].t > TMAX) last--;
  if (last <= start) { render(); return; }
  state.sweepIdx = start; render();
  var dt = Math.max(110, Math.round(2800 / (last - start + 1)));
  sweepTimer = setInterval(function () {
    if (state.sweepIdx === null || state.sweepIdx >= last) { stopSweep(); render(); return; }
    state.sweepIdx++; render();
  }, dt);
}

function updateNyq() {
  var el = document.getElementById('nyqNote');
  if (!el) return;
  if (state.Ts <= KT + 1e-9) {
    el.innerHTML = 'Nyquist interval = 0.55 &nbsp;→&nbsp; <b style="color:#178017">sampling fine: exact</b>';
  } else {
    el.innerHTML = 'Nyquist interval = 0.55 &nbsp;→&nbsp; <b style="color:#c00000">under-sampled: aliasing</b>';
  }
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The three ingredients', st: { Ts: 0.5, mode: 'Copies + sum', orig: false },
    text: 'On the left the signal exists only as blue sample impulses; in the middle sits the sinc reconstruction kernel with peak 1. The right panel is their convolution — the continuous signal recovered from discrete data.'
  },
  {
    title: 'One sample, one sinc', st: { Ts: 0.5, mode: 'Copies only', orig: false },
    text: 'Hide the sum: each blue sample plants a sinc scaled to its own height and centred at its own time. Every copy crosses zero at all the other sample instants. Click a blue sample to isolate its copy.'
  },
  {
    title: 'Sweeping the convolution', st: { Ts: 0.5, mode: 'Copies + sum', orig: false, sweep: true },
    text: 'The kernel steps across the samples one at a time and the running red total accumulates from left to right — convolution is literally this shift, scale and add process.'
  },
  {
    title: 'The sum is the signal', st: { Ts: 0.5, mode: 'Sum only', orig: false },
    text: 'Hide the copies and only the red curve remains: a smooth waveform passing exactly through every blue tip. Nothing was invented — the samples fully determined it.'
  },
  {
    title: 'Sampling too slowly', st: { Ts: 1.4, mode: 'Copies + sum', orig: true },
    text: 'Widen T_s past the Nyquist interval 0.55: the sincs become broad and overlap heavily, and the red reconstruction drifts away from the grey original between samples — this is aliasing.'
  },
  {
    title: 'Sampling densely', st: { Ts: 0.25, mode: 'Sum only', orig: true },
    text: 'Shrink T_s: narrow, tightly packed sincs rebuild the signal almost perfectly — red lies on top of the grey original. Quality is set by sample spacing, not by the kernel\'s shape.'
  }
];
var curStep = 0;

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep], st = s.st;
  stopSweep();
  state.selected = null;
  state.Ts = st.Ts; state.mode = st.mode; state.showOrig = !!st.orig;
  var sl = document.getElementById('samplingIntervalInput');
  if (sl) sl.value = st.Ts;
  var ov = document.getElementById('samplingIntervalVal');
  if (ov) ov.value = st.Ts.toFixed(2);
  var sel = document.getElementById('copyVisibilityInput');
  if (sel) sel.value = st.mode;
  var cb = document.getElementById('showOriginalInput');
  if (cb) cb.checked = !!st.orig;
  document.getElementById('demoNarration').innerHTML = '<b>' + (curStep + 1) + '. ' + s.title + '</b><br>' + s.text;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  updateNyq();
  render();
  if (st.sweep) trigger_convolutionSweep();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

/* ---------- boot ---------- */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

